using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class WhirlwindChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(){
  Check(Application.isPlaying,"Enter Play mode");var palette=UnityEngine.Object.FindAnyObjectByType<GodToolPalette>();var slice=palette.GetComponentInParent<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=slice.GetComponent<IslandNavigation>();var brush=palette.Brush;var field=typeof(QuestSlice).GetField("state",F);var original=field.GetValue(slice);var blocksField=typeof(WorldBrush).GetField("windBlocks",F);var ballsField=typeof(WorldBrush).GetField("windBalls",F);var blocks=(ConstructionBlock[])blocksField.GetValue(brush);var balls=(BeachBall[])ballsField.GetValue(brush);var ball=balls[0];var site=blocks[0].Site;var geometry=site.Capture();bool locked=site.Locked,paused=site.Paused;var tuning=slice.GetComponentInChildren<DivineIntervention>().tuning;bool unlimited=tuning.unlimitedEnergy;var test=new SliceState{developmentFocus=true};
  god.Interrupt("Whirlwind QA");foreach(var person in slice.GetComponentsInChildren<VillagerSocial>()){person.ResetTask();person.GetComponent<VillagerExploration>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.GetComponent<VillagerBlockPlay>().ResetTask();}field.SetValue(slice,test);test.Hybrid.energy=100;tuning.unlimitedEnergy=false;
  try{
   site.Paused=site.Locked=false;blocksField.SetValue(brush,Array.Empty<ConstructionBlock>());ballsField.SetValue(brush,new[]{ball});ball.ReturnHome();var point=nav.Terrain.Project(ball.transform.position);var body=ball.Body;var item=ball.GetComponent<CarryItem>();body.linearVelocity=Vector3.zero;
   float energy=test.Hybrid.energy;var before=body.linearVelocity;Check(brush.CanWhirlwind(point,out _)&&body.linearVelocity==before&&test.Hybrid.energy==energy,"Preview changed physics or energy");
   Check(brush.WhirlwindPulse(point)&&body.linearVelocity.y>0&&(body.linearVelocity-before).magnitude<=2.501f&&test.Hybrid.energy==energy-WorldBrush.WhirlwindCost,"Whirlwind did not lift with bounded paid force");before=body.linearVelocity;energy=test.Hybrid.energy;Check(!brush.WhirlwindPulse(point)&&body.linearVelocity==before&&test.Hybrid.energy==energy,"Duplicate pulse stacked force/cost");
   test.Hybrid.time+=1;item.held=true;Check(!brush.CanWhirlwind(point,out _),"Held ball stolen");item.held=false;test.Hybrid.intention.active=true;test.Hybrid.intention.target=ball.StableId;Check(!brush.CanWhirlwind(point,out _),"Creature reservation stolen");test.Hybrid.intention.active=false;
   var listener=slice.GetComponentsInChildren<VillagerExploration>().First();Check(ball.ReservePlay(listener),"Cannot reserve social ball");Check(!brush.CanWhirlwind(point,out _),"Social ball stolen");ball.CancelRally();
   ball.ReturnHome();point=nav.Terrain.Project(ball.transform.position);float start=body.position.y;brush.Stop();
   for(int i=0;i<100;i++){test.Hybrid.time+=.02f;brush.ProcessWhirlwind(point,true,.02f);ball.Advance(.02f,false);}
   Check(brush.Active&&body.position.y>start+.5f&&new Vector2(body.linearVelocity.x,body.linearVelocity.z).magnitude>1,"Native physics did not lift/orbit: "+(body.position.y-start));
   before=body.linearVelocity;brush.ProcessWhirlwind(point,false,.02f);Check(!brush.Active&&body.linearVelocity==before&&brush.GetComponentsInChildren<LineRenderer>().All(l=>!l.enabled),"Release retained force/visuals or erased momentum");
   float lifted=body.position.y;for(int i=0;i<200;i++)ball.Advance(.02f,false);Check(body.position.y<lifted,"Released ball did not fall under gravity");
   ballsField.SetValue(brush,Array.Empty<BeachBall>());var block=site.blocks.First(b=>!b.Item.held&&b.VillagerOwner==null&&site.TryPlan(b,out _,out _));blocksField.SetValue(brush,new[]{block});Check(site.TryPlan(block,out var at,out var rotation)&&site.Drop(block,at,rotation),"Cannot stage snapped block");point=nav.Terrain.Project(block.transform.position);test.Hybrid.time+=1;Check(!brush.CanWhirlwind(point,out _),"Snapped construction detached");site.Detach(block);block.Body.linearVelocity=Vector3.zero;Check(brush.WhirlwindPulse(point)&&block.Body.linearVelocity.y>0,("Loose block did not lift in site coordinates: "+brush.Reason+" held "+block.Item.held+" kin "+block.Body.isKinematic+" visitors "+site.Visitor+" requester "+site.Requester+" repair "+site.Repairer+" y "+((block.Site.World(block.Body.position)-point)/nav.Scale).y));
   block.Item.held=true;Check(!brush.CanWhirlwind(point,out _),"Held block stolen");block.Item.held=false;site.Locked=true;Check(!brush.CanWhirlwind(point,out _),"Locked site disturbed");site.Locked=false;typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(block,slice.GetComponentInChildren<VillagerBlockPlay>());Check(!brush.CanWhirlwind(point,out _),"Villager block reservation stolen");typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(block,null);
   test.paused=true;before=block.Body.linearVelocity;energy=test.Hybrid.energy;Check(!brush.ProcessWhirlwind(point,true,.02f)&&!brush.Active&&before==block.Body.linearVelocity&&energy==test.Hybrid.energy,"Pause changed world");test.paused=false;Check(!brush.CanWhirlwind(new Vector3(float.NaN,0,0),out _),"Nonfinite point accepted");
   test.Hybrid.time+=1;test.Hybrid.energy=0;Check(!brush.ProcessWhirlwind(point,true,.02f),"Unaffordable whirlwind applied");tuning.unlimitedEnergy=true;Check(!brush.ProcessWhirlwind(point,true,.02f),"Exhausted held trigger rearmed");brush.ProcessWhirlwind(point,false,.02f);Check(brush.ProcessWhirlwind(point,true,.02f)&&test.Hybrid.energy==0,"Unlimited mode failed at zero balance");
   for(int i=0;i<90;i++){test.Hybrid.time+=.1f;brush.ProcessWhirlwind(point,true,.1f);}Check(!brush.Active,"Unbounded held stroke");brush.Stop();
   palette.Select(SpiritualTool.Whirlwind);Check(palette.Selected==SpiritualTool.Whirlwind&&GodToolPalette.ToolCount==10&&palette.View.GetComponentsInChildren<Collider>(true).Count()==12,"Whirlwind missing from palette");Check(!palette.Apply(SpiritualTool.Whirlwind,null,point),"Instant use bypassed hold channel");
   test.Hybrid.time+=1;var ray=new Ray(point+Vector3.up*.2f,Vector3.down);int pulses=brush.Pulses;palette.Process(ray,true,true,false,.05f,false);Check(brush.Pulses==pulses,"Selection click leaked into casting");palette.Process(ray,false,true,false,.05f,false);palette.Process(ray,true,true,false,.05f,false);Check(brush.Pulses==pulses+1&&brush.Active,"Palette hold did not cast whirlwind");palette.Process(ray,false,true,false,.05f,false);Check(!brush.Active,"Palette release retained vortex");test.Hybrid.time+=1;palette.Process(ray,true,true,false,.05f,false);Check(brush.Active,"Second stroke did not rearm");palette.Process(ray,true,false,false,.05f,true);Check(!brush.Active&&!palette.Selected.HasValue,"Tracking loss retained vortex");
   Check(test.Hybrid.evidence.events.Any(e=>e.target=="ground-whirlwind"&&e.source==EvidenceSource.PlayerMiracle)&&!test.Hybrid.receipt.eligible&&JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Player attribution/save validation failed");
   Debug.Log("BWVR_WHIRLWIND_PASS: read-only preview, actual private-scene lift/orbit/fall, bounded paid pulses, held/creature/social/snapped/locked/villager protection, pause/nonfinite/exhaustion/rearm/timeout, unlimited energy, palette entry, player attribution and save validity");
  }finally{palette.Cancel();brush.Stop();tuning.unlimitedEnergy=unlimited;foreach(var b in blocks)typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(b,null);site.Restore(geometry);site.Locked=locked;site.Paused=paused;ball.ReturnHome();blocksField.SetValue(brush,blocks);ballsField.SetValue(brush,balls);field.SetValue(slice,original);god.NewSeason();}
 }
}
}
